sig A {}
sig B {}
sig S { f: A some -> set B, g: A set -> one B }
SomeLeft: run { some s: S | some s.f } for 2 but 0 Int
assert SomeEveryB { all s: S, b: B | some (s.f).b }
SomeEveryBHolds: check SomeEveryB for 2 but 0 Int
assert OneEveryA { all s: S, a: A | one a.(s.g) }
OneEveryAHolds: check OneEveryA for 2 but 0 Int
NoBButA: run { some A and no B and some S } for 2 but 0 Int

sig A {}
sig B {}
sig S { f: A one -> lone B }
Functional: run { some s: S | some s.f } for 2 but 0 Int
assert EachAOnce { all s: S, a: A | lone a.(s.f) }
EachAOnceHolds: check EachAOnce for 3 but 0 Int
assert Total { all s: S, b: B | one (s.f).b }
TotalHolds: check Total for 3 but 0 Int

sig P {}
sig Q { r: P -> P }
assert Composition { all q: Q | q.r.(q.r) in P -> P }
CompositionHolds: check Composition for 3 but 0 Int
ThreeWay: run { some q: Q, p: P | q -> p -> p in r } for 2 but 0 Int
Transpose: run { some q: Q | ~(q.r) = q.r and some q.r } for 2 but 0 Int
Closure: run { some q: Q | some p: P | p in p.^(q.r) } for 2 but 0 Int
Inclusion: run { r in Q -> P -> P and some r } for 2 but 0 Int
Equality: run { some disj a, b: Q | a.r = b.r and some a.r } for 2 but 0 Int

sig X {}
one sig R { t: X -> X -> X }
ProductArity: run { R.t = X -> X -> X and some X } for 2 but 0 Int
DomainRestrict: run { some x: X | x <: (R.t) != R.t } for 2 but 0 Int
RangeRestrict: run { some x: X | (R.t) :> x = R.t and some R.t } for 2 but exactly 2 X, 0 Int
UnionDiff: run { some x: X | (R.t) - (x -> X -> X) + (x -> x -> x) = R.t and some R.t } for 2 but 0 Int
Intersection: run { some R.t & (X -> X -> X) } for 2 but 0 Int
assert JoinTwice { all a, b: X | b.(a.(R.t)) in X }
JoinTwiceHolds: check JoinTwice for 2 but 0 Int

sig X {}
one sig R { t: X -> X -> X }
sig Y { u: X -> X }
RightJoin: run { some x: X | some (R.t).x and (R.t).x != x.(R.t) } for 2 but 0 Int
FieldRightJoin: run { some x: X | some u.x and no x.u } for 2 but 0 Int
MiddleJoin: run { some disj a, b: X | a.((R.t).b) != b.((R.t).a) } for 2 but 0 Int
assert RightTyped { all x: X | (R.t).x in X -> X }
RightTypedHolds: check RightTyped for 2 but 0 Int
TernaryJoinBinary: run { some y: Y | some (R.t).(y.u) } for 2 but 0 Int

sig Account {}
sig Day {}
one sig Bank { balance: Account -> Day }
Empty: run { no Bank.balance } for 2 but 0 Int
Full: run { Bank.balance = Account -> Day and some Account and some Day } for 2 but 0 Int
JoinLeft: run { some a: Account | some a.(Bank.balance) } for 2 but 0 Int
JoinRight: run { some d: Day | some (Bank.balance).d and no Account - (Bank.balance).d } for 2 but exactly 2 Account, 0 Int
assert Typed { Bank.balance in Account -> Day }
TypedHolds: check Typed for 3 but 0 Int
assert AllPairs { Bank.balance = Account -> Day }
AllPairsFails: check AllPairs for 2 but 0 Int
